const cmd=`${bin} roadmap list --json 2>/dev/null | jq '
  .items as $a |
  {
    parent_done_with_open: [
      $a[] as $c | select(.parent != "") |
      ($a[] | select(.id == $c.parent)) as $p |
      select($p.status == "done" and ($c.status == "pending" or $c.status == "blocked" or $c.status == "active")) |
      {parent:$p.id,parent_status:$p.status,child:$c.id,child_status:$c.status,child_title:$c.title}
    ],
    parent_rejected_with_open: [
      $a[] as $c | select(.parent != "") |
      ($a[] | select(.id == $c.parent)) as $p |
      select($p.status == "rejected" and ($c.status == "pending" or $c.status == "blocked" or $c.status == "active")) |
      {parent:$p.id,parent_status:$p.status,child:$c.id,child_status:$c.status}
    ],
    all_children_terminal_parent_open: [
      $a[] as $p | select(any($a[]; .parent == $p.id)) |
      ([$a[] | select(.parent == $p.id) | .status]) as $s |
      select(($p.status == "active" or $p.status == "pending" or $p.status == "blocked") and all($s[]; . == "done" or . == "rejected")) |
      {parent:$p.id,status:$p.status,child_count:($s|length),statuses:$s,title:$p.title}
    ]
  }'`;
const r=await tools.exec_command({cmd,workdir:root,yield_time_ms:10000,max_output_tokens:30000});
text(r.output);

